import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"横渠易说 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"横渠易说 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/046.md","filePath":"zh/classics/hengqu/046.md"}'),l={name:"zh/classics/hengqu/046.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><h3 id="彖曰-姤-遇也-柔遇刚也。-勿用取女-不可与长也。天地相遇-品物咸章也-刚遇中正-天下大行也。姤之时义大矣哉" tabindex="-1">彖曰：姤，遇也，柔遇刚也。“勿用取女”，不可与长也。天地相遇，品物咸章也，刚遇中正，天下大行也。姤之时义大矣哉! <a class="header-anchor" href="#彖曰-姤-遇也-柔遇刚也。-勿用取女-不可与长也。天地相遇-品物咸章也-刚遇中正-天下大行也。姤之时义大矣哉" aria-label="Permalink to “彖曰：姤，遇也，柔遇刚也。“勿用取女”，不可与长也。天地相遇，品物咸章也，刚遇中正，天下大行也。姤之时义大矣哉!”">​</a></h3><p>非中爻不能备卦德，故曰“刚遇中正”。</p><h3 id="象曰-天下有风-姤-后以施命诰四方。" tabindex="-1">象曰：天下有风，姤，后以施命诰四方。 <a class="header-anchor" href="#象曰-天下有风-姤-后以施命诰四方。" aria-label="Permalink to “象曰：天下有风，姤，后以施命诰四方。”">​</a></h3><p>上所以用柔于下者，诰令莫大焉。</p><h3 id="初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅。-象曰-系于金柅-柔道牵也。" tabindex="-1">初六，系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。 象曰：“系于金柅”，柔道牵也。 <a class="header-anchor" href="#初六-系于金柅-贞吉。有攸往-见凶。羸豕孚蹢躅。-象曰-系于金柅-柔道牵也。" aria-label="Permalink to “初六，系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。 象曰：“系于金柅”，柔道牵也。”">​</a></h3><p>金柅二物也，处姤之时，不牵于近则所往皆凶。孚，信也。豕方羸时，力未能动，然至诚在于蹢躅，得申则申矣。如李德裕处置阉宦，徒知其帖息威伏，而忽于志不(忘)［妄］逞，照察少不至则失其几也。</p><h3 id="九二-包有鱼-无咎-不利宾。-象曰-包有鱼-义不及宾也。" tabindex="-1">九二，包有鱼，无咎，不利宾。 象曰：“包有鱼”，义不及宾也。 <a class="header-anchor" href="#九二-包有鱼-无咎-不利宾。-象曰-包有鱼-义不及宾也。" aria-label="Permalink to “九二，包有鱼，无咎，不利宾。 象曰：“包有鱼”，义不及宾也。”">​</a></h3><h3 id="九三-臀无肤-其行次且-厉无大咎。-象曰-其行次且-行未牵也。" tabindex="-1">九三，臀无肤，其行次且，厉无大咎。 象曰：“其行次且”，行未牵也。 <a class="header-anchor" href="#九三-臀无肤-其行次且-厉无大咎。-象曰-其行次且-行未牵也。" aria-label="Permalink to “九三，臀无肤，其行次且，厉无大咎。 象曰：“其行次且”，行未牵也。”">​</a></h3><p>行而无所与遇，故曰“行未牵也”，进退无所系也。</p><h3 id="九四-包无鱼-起凶。-象曰-无鱼之凶-远民也。" tabindex="-1">九四，包无鱼，起凶。 象曰：无鱼之凶，远民也。 <a class="header-anchor" href="#九四-包无鱼-起凶。-象曰-无鱼之凶-远民也。" aria-label="Permalink to “九四，包无鱼，起凶。 象曰：无鱼之凶，远民也。”">​</a></h3><h3 id="九五-以杞包瓜-含章-有陨自天。-象曰-九五含章-中正也。-有陨自天-志不舍命也。" tabindex="-1">九五，以杞包瓜，含章，有陨自天。 象曰：九五含章，中正也。“有陨自天”，志不舍命也。 <a class="header-anchor" href="#九五-以杞包瓜-含章-有陨自天。-象曰-九五含章-中正也。-有陨自天-志不舍命也。" aria-label="Permalink to “九五，以杞包瓜，含章，有陨自天。 象曰：九五含章，中正也。“有陨自天”，志不舍命也。”">​</a></h3><p>杞之为物，根固于下，瓜之为实，溃必自内。九五以中正刚健含章宅尊，而遇阴柔浸长之时，厚下安宅，溃乱是防，尽其人谋而听天命者也。“以杞包瓜”，文王事纣之道，厚下以防中溃，尽人谋而听天命者欤!</p><h3 id="上九-姤其角-吝无咎。-象曰-姤其角-上穷吝也。" tabindex="-1">上九，姤其角，吝无咎。 象曰：“姤其角”，上穷吝也。 <a class="header-anchor" href="#上九-姤其角-吝无咎。-象曰-姤其角-上穷吝也。" aria-label="Permalink to “上九，姤其角，吝无咎。 象曰：“姤其角”，上穷吝也。”">​</a></h3><p>穷不知变，吝之道也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
